bool Read_RmlElementStringListResult(const WasmValue& input, RmlElementStringListResult& output, NativeCallStorage& storage, std::string& error)
{
	const auto* record = std::get_if<WasmValueRecord>(&input.storage);
	if (record == nullptr) { error = "Wasm argument is not a record"; return false; }
	const auto* value_values = FindRecordField(*record, "values", error);
	if (value_values == nullptr) return false;
	const auto* list_values = std::get_if<WasmValueList>(&(*value_values).storage);
	if (list_values == nullptr) { error = "Wasm argument is not a list"; return false; }
	auto& native_values = storage.Make<std::vector<std::string>>();
	native_values.reserve(list_values->size());
	for (const auto& item : *list_values) {
		std::string item_value{};
		auto& stored_string_item_value = storage.Make<std::string>();
		if (!ReadString(item, stored_string_item_value, error)) { return false; }
		item_value = stored_string_item_value.c_str();
		native_values.push_back(std::move(item_value));
	}
	auto& pointers_values = storage.Make<std::vector<const char*>>();
	pointers_values.reserve(native_values.size());
	for (const auto& item : native_values) pointers_values.push_back(item.c_str());
	output.values = pointers_values.data();
	if (!AssignCount(list_values->size(), output.valueCount, error)) { return false; }
	return true;
}

