{
	WasmValueRecord fields;
	fields.emplace("values", WriteNativeList(value.values, value.valueCount, [](const auto& value) { return WasmValue::String(value == nullptr ? std::string{} : std::string(value)); }));
	return WasmValue::Record(std::move(fields));
}

