NativeCalloutDispatch Dispatch_rml_ui_AddTranslationString(NativeInterface* nativeInterface, const std::vector<WasmValue>& arguments, WasmValue& result, std::string& error)
{
	if (nativeInterface == nullptr || nativeInterface->rmlUi == nullptr || nativeInterface->rmlUi->AddTranslationString == nullptr) { error = "NativeInterface API is unavailable: rml_ui.AddTranslationString"; return NativeCalloutDispatch::handled; }
	NativeCallStorage storage;
	RmlAddTranslationStringQuery query{};
	RmlAddTranslationStringResult nativeResult{};
	const WasmValue* value_key = FindArgument(arguments, 0u, 0u, 2u, 2u, "key", error);
	if (value_key == nullptr) return NativeCalloutDispatch::handled;
	auto& stored_string_query_key = storage.Make<std::string>();
	if (!ReadString(*value_key, stored_string_query_key, error)) { return NativeCalloutDispatch::handled; }
	query.key = stored_string_query_key.c_str();
	const WasmValue* value_translation = FindArgument(arguments, 1u, 1u, 2u, 2u, "translation", error);
	if (value_translation == nullptr) return NativeCalloutDispatch::handled;
	auto& stored_string_query_translation = storage.Make<std::string>();
	if (!ReadString(*value_translation, stored_string_query_translation, error)) { return NativeCalloutDispatch::handled; }
	query.translation = stored_string_query_translation.c_str();
	nativeInterface->rmlUi->AddTranslationString(&query, &nativeResult);
	if (!CheckNativeError(nativeResult, error)) return NativeCalloutDispatch::handled;
	result = WriteScalar(nativeResult.success);
	return NativeCalloutDispatch::handled;
}

